#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=198.51.100.200/32 --layer4-configs=udp:514 '--description=ipv4rule 4'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=198.51.100.200/32 --layer4-configs=udp:514 '--description=ipv4rule 4'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=192.168.10.0/24 --layer4-configs=tcp:102 --enable-logging '--description=ipv4rule 2'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=192.168.10.0/24 --layer4-configs=tcp:102 --enable-logging '--description=ipv4rule 2'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=198.51.100.10/32 --dest-ip-ranges=192.168.10.20/32 --layer4-configs=tcp:4840 --enable-logging '--description=ipv4rule 1'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=198.51.100.10/32 --dest-ip-ranges=192.168.10.20/32 --layer4-configs=tcp:4840 --enable-logging '--description=ipv4rule 1'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=198.51.100.40/29,198.51.100.48/31 --dest-ip-ranges=192.168.10.30/32 --layer4-configs=tcp:502 '--description=ipv4rule 3'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=198.51.100.40/29,198.51.100.48/31 --dest-ip-ranges=192.168.10.30/32 --layer4-configs=tcp:502 '--description=ipv4rule 3'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=192.168.30.10/32 --layer4-configs=tcp:443 --enable-logging '--description=ipv4rule 6'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=192.168.30.10/32 --layer4-configs=tcp:443 --enable-logging '--description=ipv4rule 6'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.168.30.0/24 --dest-ip-ranges=192.168.10.0/24 --layer4-configs=all --enable-logging '--description=ipv4rule 8'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.168.30.0/24 --dest-ip-ranges=192.168.10.0/24 --layer4-configs=all --enable-logging '--description=ipv4rule 8'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=192.168.30.0/24 --layer4-configs=47 '--description=ipv4rule 9'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=192.168.30.0/24 --layer4-configs=47 '--description=ipv4rule 9'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.20.0.0/16,192.168.10.0/24 --dest-ip-ranges=10.20.0.0/16,192.168.10.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan1
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.20.0.0/16,192.168.10.0/24 --dest-ip-ranges=10.20.0.0/16,192.168.10.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan1
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan2
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan2
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.30.0/24 --dest-ip-ranges=192.168.30.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan3
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.30.0/24 --dest-ip-ranges=192.168.30.0/24 --layer4-configs=all --description=fwshift-intrazone-vlan3
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1230 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   ipv4rule 5: what it allows cannot be said by a rule of Google Cloud
#   ipv4rule 7: what it allows cannot be said by a rule of Google Cloud
#   ipv4rule 11: not converted: source DYNAMIC: the address of the user who activates the rule set, or of the digital input
#   ipv4rule 12: not converted: service ENIP is not in the configuration; references 'ENIP': unsupported or undefined service
#   ipv4rule 13: the source of the rule is in zone ipsecALL, and a rule of Google Cloud names no zone: give the networks behind ipsecALL with --zone-network
#   ipv4rule 14: not converted: assigned to the rule set maintenance: it applies only while the set is activated (by a user or a digital input)
#   ipv4rule 15: what it allows cannot be said by a rule of Google Cloud

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
